suppressPackageStartupMessages({library(survey);library(splines);library(jsonlite);library(foreign)})
options(survey.lonely.psu='fail',contrasts=c('contr.treatment','contr.poly'))
iout<-'analysis/tasks/V3-I01/rev-1/work';qout<-'analysis/tasks/V3-Q01/rev-1/work';a<-readRDS(file.path(iout,'prepared.rds'));b<-a$base
near<-function(x,y,tol=1e-7)stopifnot(isTRUE(all.equal(as.numeric(x),as.numeric(y),tolerance=tol,check.attributes=FALSE)))
full<-svydesign(id=~SDMVPSU,strata=~SDMVSTRA,weights=~weight_mec_18yr,nest=TRUE,data=b[is.finite(b$weight_mec_18yr)&b$weight_mec_18yr>0,]);d<-subset(full,model2_domain);d$variables<-droplevels(d$variables);d$variables$x<-log(d$variables$NLR)
f<-svyglm(reformulate(c('x',a$m2),'frail'),d,family=quasibinomial());z<-read.csv(file.path(iout,'continuous_models.csv'));r<-subset(z,model=='M2'&marker=='NLR');near(r$beta,coef(f)['x']);near(r$se,sqrt(vcov(f)['x','x']))
fint<-svyglm(reformulate(c(setdiff(a$m2,'bmi'),'x*bmi'),'frail'),d,family=quasibinomial());terms<-grep('x:bmi',names(coef(fint)),value=TRUE);bb<-coef(fint)[terms];V<-vcov(fint)[terms,terms];F<-drop(t(bb)%*%solve(V,bb))/length(bb);ints<-read.csv(file.path(iout,'interactions.csv'));rr<-subset(ints,marker=='NLR'&moderator=='bmi');near(rr$F,F);near(rr$p,pf(F,length(bb),degf(d),lower.tail=FALSE));slopes<-read.csv(file.path(iout,'subgroup_slopes.csv'));for(l in levels(d$variables$bmi)){L<-setNames(rep(0,length(coef(fint))),names(coef(fint)));L['x']<-1;if(l!=levels(d$variables$bmi)[1])L[paste0('x:bmi',l)]<-1;est<-sum(L*coef(fint));se<-sqrt(drop(t(L)%*%vcov(fint)%*%L));r<-subset(slopes,marker=='NLR'&moderator=='bmi'&level==l);near(r$OR,exp(est));near(r$low,exp(est-qt(.975,degf(d))*se));near(r$high,exp(est+qt(.975,degf(d))*se))}
# Independent natural-spline parameterization; compare entire curve to I residualized basis.
k<-quantile(d$variables$x,c(1/3,2/3));bd<-range(d$variables$x);B<-ns(d$variables$x,knots=k,Boundary.knots=bd);d$variables$bs1<-B[,1];d$variables$bs2<-B[,2];d$variables$bs3<-B[,3];fs<-svyglm(reformulate(c('bs1','bs2','bs3',a$m2),'frail'),d,family=quasibinomial());cc<-subset(read.csv(file.path(iout,'curve_data.csv')),model=='M2'&marker=='NLR');G<-ns(log(cc$value),knots=k,Boundary.knots=bd);R<-ns(log(cc$reference),knots=k,Boundary.knots=bd);C<-G-R;ix<-match(c('bs1','bs2','bs3'),names(coef(fs)));est<-drop(C%*%coef(fs)[ix]);se<-sqrt(rowSums((C%*%vcov(fs)[ix,ix])*C));near(cc$OR,exp(est));near(cc$low,exp(est-qt(.975,degf(d))*se));near(cc$high,exp(est+qt(.975,degf(d))*se))
# Raw-weight and raw1999status independent comparisons.
old<-read.xport('analysis/data/raw/1999-2000/DRXTOT.xpt');i<-match(b$SEQN,old$SEQN);valid99<-b$cycle=='1999-2000'&!is.na(b$energy);valid99[is.na(valid99)]<-FALSE;stopifnot(all(old$DRDDRSTS[i[valid99]]==1));near(b$energy[valid99],old$DRXTKCAL[i[valid99]])
for(cy in sort(unique(b$cycle))[3:9]){p<-list.files(file.path('analysis/data/raw',cy),pattern='^DR2TOT.*xpt$',full.names=TRUE);raw<-read.xport(p);ix<-which(b$cycle==cy);near(b$weight_diet14[ix],raw$WTDR2D[match(b$SEQN[ix],raw$SEQN)]/7)}
diet<-svydesign(id=~SDMVPSU,strata=~SDMVSTRA,weights=~weight_diet14,nest=TRUE,data=b[is.finite(b$weight_diet14)&b$weight_diet14>0,]);dd<-subset(diet,diet_domain);dd$variables<-droplevels(dd$variables);dd$variables$x<-log(dd$variables$NLR);dd$variables$energy<-dd$variables$energy2;fd<-svyglm(reformulate(c('x',a$m2),'frail'),dd,family=quasibinomial());r<-subset(z,model=='Diet_mean2_matched'&marker=='NLR');near(r$beta,coef(fd)['x']);near(r$se,sqrt(vcov(fd)['x','x']))
write_json(list(status='PASS',main_n=nrow(d$variables),diet_n=nrow(dd$variables),checks=c('IndependentNLRModel2betaSE','IndependentNLRBMIinteractionWald','IndependentNLRBMIalllevelcovarianceCIs','IndependentNLR3dfcurvealternativebasisallpoints','Raw1999statusenergy','Rawall7dietweights','IndependentNLRmean2dietbetaSE')),file.path(qout,'independent_model_checks.json'),pretty=TRUE,auto_unbox=TRUE);cat('INDEPENDENT FIT CHECKS PASS\n')
